const requested = new Set();
function loadOne(id) {
  if (!ART_FILES[id] && id.startsWith('eigen_') && EIGEN_ZELLEN[id.slice(6)]) { loadSheet(EIGEN_ZELLEN[id.slice(6)][0]); return; }
  if (requested.has(id) || !ART_FILES[id]) return;
  requested.add(id);
  const im = new Image();
  im.decoding = 'async';
  im.onload = () => { ART[id] = im; for (const f of artListeners) f(id); };
  im.src = ART_FILES[id];
}
// Einen Bogen aus Paket 6 laden und in seine Bilder zerschneiden (eigen_<name> als Leinwand)
function loadSheet(sheet) {
  const sid = `eigenbogen_${sheet}`;
  if (requested.has(sid) || !ART_FILES[sid]) return;
  requested.add(sid);
  const im = new Image();
  im.decoding = 'async';
  im.onload = () => {
    for (const [name, z] of Object.entries(EIGEN_ZELLEN)) {
      if (z[0] !== sheet) continue;
      const cv = document.createElement('canvas'); cv.width = z[3]; cv.height = z[4];
      cv.getContext('2d').drawImage(im, z[1], z[2], z[3], z[4], 0, 0, z[3], z[4]);
      ART[`eigen_${name}`] = cv;
      for (const f of artListeners) f(`eigen_${name}`);
    }
  };
  im.src = ART_FILES[sid];
}
export function loadArt() {
  for (const id of Object.keys(ART_FILES)) if (!LAZY.test(id)) loadOne(id);
}
// Bild bei Bedarf anfordern; gibt es schon geladen zurück, sonst null (es kommt später)
// Gibt es dieses Bild überhaupt (geladen oder nicht)?
export function artKnown(id) { return !!ART_FILES[id] || (id.startsWith('eigen_') && !!EIGEN_ZELLEN[id.slice(6)]); }
export function wantArt(id) {
  const im = ART[id];
  if (im) return im;
  loadOne(id);
  return null;
}
// Alle Bilder mit diesem Anfang anfordern (z. B. alle Bewegungen eines Modells)
export function wantArtPrefix(prefix) {
  if (requested.has('#' + prefix)) return;
  requested.add('#' + prefix);
  for (const id of Object.keys(ART_FILES)) if (id.startsWith(prefix)) loadOne(id);
}
